import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { dirname, join, resolve, sep } from 'node:path';
import { Readable } from 'node:stream';
import { del, get, put } from '@vercel/blob';

/** Private file storage for CVs. Keys are generated by the server ("cvs/<ownerId>/<uuid>.pdf"), never taken from clients. */
export interface FileStorage {
  put(key: string, bytes: Buffer, contentType: string): Promise<void>;
  /** null when the file does not exist. */
  get(key: string): Promise<{ stream: ReadableStream<Uint8Array>; size: number } | null>;
  /** Deleting a missing file is not an error. */
  del(key: string): Promise<void>;
}

/** Vercel Blob, private store. Authenticates with BLOB_READ_WRITE_TOKEN, or OIDC + BLOB_STORE_ID when connected on Vercel. */
const blobStorage: FileStorage = {
  async put(key, bytes, contentType) {
    await put(key, bytes, { access: 'private', contentType, addRandomSuffix: false, allowOverwrite: false });
  },
  async get(key) {
    const res = await get(key, { access: 'private' });
    if (!res || res.statusCode !== 200) return null;
    return { stream: res.stream, size: res.blob.size };
  },
  async del(key) {
    await del(key);
  },
};

/** Local development only: plain files under .data/uploads (git-ignored). */
const LOCAL_ROOT = resolve(/*turbopackIgnore: true*/ process.env.LOCAL_UPLOAD_DIR || '.data/uploads');
function localPath(key: string): string {
  const full = resolve(/*turbopackIgnore: true*/ join(LOCAL_ROOT, key));
  if (!full.startsWith(LOCAL_ROOT + sep)) throw new Error('Invalid storage key');
  return full;
}
const localStorage: FileStorage = {
  async put(key, bytes) {
    const path = localPath(key);
    await mkdir(/*turbopackIgnore: true*/ dirname(path), { recursive: true });
    await writeFile(/*turbopackIgnore: true*/ path, bytes, { flag: 'wx' });
  },
  async get(key) {
    const path = localPath(key);
    const size = await stat(/*turbopackIgnore: true*/ path).then((s) => s.size, () => null);
    if (size === null) return null;
    return { stream: Readable.toWeb(createReadStream(/*turbopackIgnore: true*/ path)) as ReadableStream<Uint8Array>, size };
  },
  async del(key) {
    await rm(/*turbopackIgnore: true*/ localPath(key), { force: true });
  },
};

let override: FileStorage | null = null;
/** Tests swap the storage; pass null to restore the default. */
export function setFileStorage(s: FileStorage | null): void {
  override = s;
}

export function fileStorage(): FileStorage {
  if (override) return override;
  if (process.env.BLOB_READ_WRITE_TOKEN || process.env.BLOB_STORE_ID) return blobStorage;
  if (process.env.NODE_ENV === 'production') {
    throw new Error('File storage is not configured: set BLOB_READ_WRITE_TOKEN (or connect a private Vercel Blob store)');
  }
  return localStorage;
}

/** In-memory storage for tests. */
export function memoryStorage(): FileStorage & { files: Map<string, Buffer> } {
  const files = new Map<string, Buffer>();
  return {
    files,
    async put(key, bytes) {
      files.set(key, bytes);
    },
    async get(key) {
      const bytes = files.get(key);
      if (!bytes) return null;
      return { stream: new Blob([new Uint8Array(bytes)]).stream() as ReadableStream<Uint8Array>, size: bytes.length };
    },
    async del(key) {
      files.delete(key);
    },
  };
}

export const readAll = async (stream: ReadableStream<Uint8Array>): Promise<Buffer> =>
  Buffer.from(await new Response(stream).arrayBuffer());
